import {useState} from 'react';import {useNavigate} from 'react-router-dom';import {LibraryBig,LockKeyhole,UserRoundPlus} from 'lucide-react';import api,{message} from '../services/api.js';
export default function Login(){const nav=useNavigate();const [mode,setMode]=useState('login');const [form,setForm]=useState({username:'admin',name:'',email:'',password:'admin123'});const [error,setError]=useState('');const [busy,setBusy]=useState(false);function change(k,v){setForm(x=>({...x,[k]:v}))}async function submit(e){e.preventDefault();setBusy(true);setError('');try{const r=await api.post(mode==='login'?'/auth/login':'/auth/register',form);localStorage.setItem('library_token',r.data.token);localStorage.setItem('library_user',JSON.stringify(r.data.user));nav(r.data.user.role==='admin'?'/':'/my-account');}catch(e){setError(message(e));}finally{setBusy(false)}}return <div className="login-page"><div className="login-card"><div className="login-brand"><span><LibraryBig/></span><h1>Libra</h1><p>Library Management System</p></div><div className="auth-tabs"><button className={mode==='login'?'selected':''} onClick={()=>{setMode('login');setError('')}}>Sign in</button><button className={mode==='register'?'selected':''} onClick={()=>{setMode('register');setError('')}}>Create account</button></div><form onSubmit={submit}>{mode==='register'&&<><label>Full name<input value={form.name} onChange={e=>change('name',e.target.value)} required autoComplete="name"/></label><label>Email address<input type="email" value={form.email} onChange={e=>change('email',e.target.value)} required autoComplete="email"/></label><label>Username<input value={form.username} onChange={e=>change('username',e.target.value)} required autoComplete="username"/></label></>}{mode==='login'&&<label>Username or email<input value={form.username} onChange={e=>change('username',e.target.value)} required autoComplete="username"/></label>}<label>Password<div className="input-icon"><LockKeyhole size={17}/><input type="password" minLength={mode==='register'?8:1} value={form.password} onChange={e=>change('password',e.target.value)} required autoComplete={mode==='login'?'current-password':'new-password'}/></div>{mode==='register'&&<small>Use at least 8 characters.</small>}</label>{error&&<div className="alert error">{error}</div>}<button className="btn primary full" disabled={busy}>{busy?'Please wait…':mode==='login'?'Sign in':'Create member account'}</button></form>{mode==='login'?<small className="hint">Administrator demo: admin / admin123. Members can sign in with their registered username or email.</small>:<small className="hint"><UserRoundPlus size={14}/> Registration creates a member account. It does not issue any books.</small>}</div></div>}
